<?php
require_once __DIR__.'/includes/bootstrap.php';require_role(['admin','accueil']);$page_title='Gestion des clients';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['nom']??''));$firstName=trim((string)($_POST['prenom']??''));$phone=trim((string)($_POST['telephone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['adresse']??''));if($name===''||mb_strlen($name)>120||mb_strlen($firstName)>120||!preg_match('/^\+?[0-9()\s.-]{6,30}$/',$phone)||($email!==''&&filter_var($email,FILTER_VALIDATE_EMAIL)===false)||mb_strlen($address)>255){flash('Vérifiez le nom, le téléphone, l’e-mail et l’adresse.','error');redirect('clients.php');}$s=db()->prepare('INSERT INTO clients(nom,prenom,telephone,email,adresse,cree_par) VALUES(?,?,?,?,?,?)');$s->execute([$name,$firstName?:null,$phone,$email?:null,$address?:null,(int)$_SESSION['user']['id']]);$clientId=(int)db_last_insert_id(db(),'clients');audit_event('CREATE','clients',$clientId);flash('Client ajouté avec succès.');redirect('clients.php');}
$rows=db()->query("SELECT c.*,c.cree_le AS created_at,COUNT(o.id) commandes FROM clients c LEFT JOIN commandes o ON o.client_id=c.id WHERE c.supprime=0 GROUP BY c.id ORDER BY c.id DESC LIMIT 500")->fetchAll();require 'includes/header.php';?>
<div class="panel"><div class="panel-head"><h2>Nouveau client</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Nom *</label><input name="nom" required></div><div class="field"><label>Prénom</label><input name="prenom"></div><div class="field"><label>Téléphone *</label><input name="telephone" required placeholder="6XXXXXXXX"></div><div class="field"><label>E-mail</label><input type="email" name="email"></div><div class="field full"><label>Adresse</label><input name="adresse"></div><div><button class="btn">Enregistrer le client</button></div></form></div>
<div class="panel"><div class="panel-head"><h2>Répertoire clients (<?=count($rows)?>)</h2><input class="search" data-filter="#clients" placeholder="Rechercher un client..."></div><div class="table-wrap"><table id="clients"><thead><tr><th>Nom complet</th><th>Téléphone</th><th>E-mail</th><th>Commandes</th><th>Inscription</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['prenom'].' '.$r['nom'])?></b></td><td><?=e($r['telephone'])?></td><td><?=e($r['email'])?></td><td><?=e($r['commandes'])?></td><td><?=date('d/m/Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require 'includes/footer.php';?>
